import pandas as pd

def calculate_final_prices(products: pd.DataFrame, discounts: pd.DataFrame) -> pd.DataFrame:
    merged = pd.merge(products, discounts, on='category', how='left')
    merged['discount'] = merged['discount'].fillna(0)
    merged['final_price'] = (merged['price'] * (1 - merged['discount'] / 100.0)).round(2)
    return merged[['product_id', 'final_price', 'category']].sort_values('product_id')
